//! Query coverage is authorized only after the engine has checked its source.
use super::*;
use std::sync::atomic::AtomicBool;
use std::time::SystemTime;
#[cfg(windows)]
mod windows;

struct Source {
    path: PathBuf,
    len: u64,
    modified: Option<SystemTime>,
    #[cfg(windows)]
    last_write_time: u64,
}
impl Source {
    fn unchanged(&self) -> Result<bool> {
        let Some(modified) = self.modified else {
            return Ok(false);
        };
        #[cfg(windows)]
        if let Some((len, last_write_time)) = {
            #[cfg(feature = "diagnostic-timing")]
            let _native = crate::timing::span("query.covering_native_lookup");
            windows::source_stamp(&self.path)
        } {
            return if len == self.len && last_write_time == self.last_write_time {
                Ok(true)
            } else {
                Err(Error::Corrupt(
                    "covered source changed since bound open".into(),
                ))
            };
        }
        #[cfg(feature = "diagnostic-timing")]
        let _fallback = crate::timing::span("query.covering_source_fallback");
        let metadata = std::fs::metadata(&self.path)?;
        let Ok(current) = metadata.modified() else {
            return Ok(false);
        };
        if metadata.len() != self.len || current != modified {
            return Err(Error::Corrupt(
                "covered source changed since bound open".into(),
            ));
        }
        Ok(true)
    }
}

pub(super) struct Covering {
    authorized: AtomicBool,
    len: u64,
    modified: Option<SystemTime>,
    source: Option<Source>,
    universal: Universal,
}
impl Covering {
    pub fn new(metadata: &std::fs::Metadata) -> Self {
        Self {
            authorized: AtomicBool::new(false),
            len: metadata.len(),
            modified: metadata.modified().ok(),
            source: None,
            universal: Universal::default(),
        }
    }
    pub fn with_grams(mut self, universal: Universal) -> Self {
        self.universal = universal;
        self
    }
    pub fn short_covered(&self, scope: &str, term: &str) -> bool {
        self.universal.covers(scope, term)
    }
    pub fn root_bytes(&self) -> usize {
        self.universal.root_bytes()
    }
    pub fn bind_source(&mut self, path: PathBuf) -> Result<()> {
        let metadata = std::fs::metadata(&path)?;
        self.source = Some(Source {
            path,
            len: metadata.len(),
            modified: metadata.modified().ok(),
            #[cfg(windows)]
            last_write_time: {
                use std::os::windows::fs::MetadataExt;
                metadata.last_write_time()
            },
        });
        Ok(())
    }
    pub fn authorize(&self) {
        self.authorized.store(true, Ordering::Release);
    }
    pub fn usable(&self, file: &File) -> Result<bool> {
        #[cfg(feature = "diagnostic-timing")]
        let _guard = crate::timing::span("query.covering_guard");
        if !self.authorized.load(Ordering::Acquire) || self.modified.is_none() {
            return Ok(false);
        }
        let Some(source) = &self.source else {
            return Ok(false);
        };
        let unchanged = {
            #[cfg(feature = "diagnostic-timing")]
            let _source = crate::timing::span("query.covering_source_metadata");
            source.unchanged()?
        };
        if !unchanged {
            return Ok(false);
        }
        let metadata = {
            #[cfg(feature = "diagnostic-timing")]
            let _index = crate::timing::span("query.covering_index_metadata");
            file.metadata()?
        };
        let Ok(modified) = metadata.modified() else {
            return Ok(false);
        };
        if metadata.len() != self.len || Some(modified) != self.modified {
            return Err(Error::Corrupt(
                "covered index changed since validated open".into(),
            ));
        }
        Ok(true)
    }
}

// Gram postings are exact substring evidence only for one complete trigram.
// Count Unicode scalars after folding; byte length and word boundaries differ.
pub(super) fn exact_gram(term: &str) -> bool {
    let mut chars = term.chars();
    (0..3).all(|_| chars.next().is_some_and(|c| !c.is_whitespace())) && chars.next().is_none()
}

// A full-live posting proves every substring of its gram in that scope.
// This is positive evidence only: isolated short text has no gram at all.
// Keep a bounded summary while parsing the existing directory, never full text.
#[derive(Default)]
pub(super) struct Universal {
    grams: Vec<(Box<str>, Box<str>)>,
    string_bytes: usize,
}
impl Universal {
    const ENTRIES: usize = 64;
    const BYTES: usize = 16 * 1024;
    pub fn observe(&mut self, term: &Term, count: u32, live: usize) {
        if live == 0 || count as usize != live || self.grams.len() == Self::ENTRIES {
            return;
        }
        let Term::Gram(scope, gram) = term else {
            return;
        };
        if !exact_gram(gram)
            || Self::ENTRIES * std::mem::size_of::<(Box<str>, Box<str>)>()
                + self.string_bytes
                + scope.len()
                + gram.len()
                > Self::BYTES
        {
            return;
        }
        if self.grams.is_empty() {
            self.grams.reserve_exact(Self::ENTRIES);
        }
        self.string_bytes += scope.len() + gram.len();
        self.grams
            .push((scope.as_str().into(), gram.as_str().into()));
    }
    fn covers(&self, scope: &str, term: &str) -> bool {
        let mut chars = term.chars();
        if !chars.next().is_some_and(|c| !c.is_whitespace())
            || !chars.next().is_some_and(|c| !c.is_whitespace())
            || chars.next().is_some()
        {
            return false;
        }
        self.grams
            .iter()
            .any(|(s, gram)| s.as_ref() == scope && gram.contains(term))
    }
    fn root_bytes(&self) -> usize {
        self.grams.capacity() * std::mem::size_of::<(Box<str>, Box<str>)>() + self.string_bytes
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn complete_gram_is_unicode_scalar_based() {
        for text in ["the", "man", "東京🦀", "éçü", "a\u{0301}x"] {
            assert!(exact_gram(text));
            assert_eq!(grams(text), BTreeSet::from([text.to_owned()]));
        }
        for text in ["", "a", "he", "four", "a b", "a\nβ", " a "] {
            assert!(!exact_gram(text));
        }
    }
    #[test]
    fn short_proof_is_positive_scoped_complete_and_bounded() {
        let mut proof = Universal::default();
        for (gram, count) in [("the", 3), ("東京🦀", 3), ("xyz", 2), ("bad!", 3)] {
            proof.observe(&Term::Gram("s".into(), gram.into()), count, 3);
        }
        for term in ["he", "th", "東京", "京🦀"] {
            assert!(proof.covers("s", term));
            assert!(!proof.covers("other", term));
        }
        for term in ["xy", "ba", "zx", "h", "the", "", "h e"] {
            assert!(!proof.covers("s", term));
        }
        for n in 0..1000 {
            proof.observe(&Term::Gram("s".into(), format!("{n:03}")), 3, 3);
            assert!(proof.root_bytes() <= Universal::BYTES);
            assert!(proof.grams.len() <= Universal::ENTRIES);
        }
        let before = proof.root_bytes();
        proof.observe(&Term::Gram("s".into(), "end".into()), 3, 3);
        assert_eq!(proof.root_bytes(), before);
        let mut empty = Universal::default();
        empty.observe(
            &Term::Gram("s".repeat(Universal::BYTES), "the".into()),
            1,
            1,
        );
        empty.observe(&Term::Gram("s".into(), "the".into()), 0, 0);
        assert_eq!(empty.root_bytes(), 0);
    }
}

use std::{mem::MaybeUninit, os::windows::ffi::OsStrExt, path::Path};
use windows_sys::Win32::Storage::FileSystem::{
    FILE_ATTRIBUTE_DIRECTORY, FILE_ATTRIBUTE_REPARSE_POINT, GetFileAttributesExW,
    GetFileExInfoStandard, WIN32_FILE_ATTRIBUTE_DATA,
};

// A link's attributes describe the link, whereas std::fs::metadata follows it.
// Unsupported paths, links and API errors must use the existing metadata path.
pub(super) fn source_stamp(path: &Path) -> Option<(u64, u64)> {
    let mut wide: Vec<_> = path.as_os_str().encode_wide().collect();
    if wide.contains(&0) {
        return None;
    }
    wide.push(0);
    let mut attributes = MaybeUninit::<WIN32_FILE_ATTRIBUTE_DATA>::uninit();
    // SAFETY: wide is NUL-terminated and lives across this synchronous call;
    // the output is correctly sized/aligned for GetFileExInfoStandard.
    let success = unsafe {
        GetFileAttributesExW(
            wide.as_ptr(),
            GetFileExInfoStandard,
            attributes.as_mut_ptr().cast(),
        )
    };
    if success == 0 {
        return None;
    }
    // SAFETY: the successful API call initialized all fields of this struct.
    let attributes = unsafe { attributes.assume_init() };
    if attributes.dwFileAttributes & (FILE_ATTRIBUTE_REPARSE_POINT | FILE_ATTRIBUTE_DIRECTORY) != 0
    {
        return None;
    }
    Some((
        (u64::from(attributes.nFileSizeHigh) << 32) | u64::from(attributes.nFileSizeLow),
        (u64::from(attributes.ftLastWriteTime.dwHighDateTime) << 32)
            | u64::from(attributes.ftLastWriteTime.dwLowDateTime),
    ))
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::{fs, os::windows::fs::MetadataExt, path::PathBuf, time::Duration};

    struct Temp(PathBuf);
    impl Temp {
        fn new() -> Self {
            let directory = std::env::temp_dir().join(format!(
                "fdb-stamp-{}-{}",
                std::process::id(),
                std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap()
                    .as_nanos()
            ));
            fs::create_dir(&directory).unwrap();
            Self(directory)
        }
    }
    impl Drop for Temp {
        fn drop(&mut self) {
            let _ = fs::remove_dir_all(&self.0);
        }
    }
    fn stamp(path: &Path) -> (u64, u64) {
        let metadata = fs::metadata(path).unwrap();
        (metadata.file_size(), metadata.last_write_time())
    }

    #[test]
    fn native_stamp_matches_std_for_unicode_resize_same_size_changes_and_missing_paths() {
        let temp = Temp::new();
        let path = temp.0.join("İş 東京 🦀.fdb");
        fs::write(&path, b"abc").unwrap();
        assert_eq!(source_stamp(&path), Some(stamp(&path)));
        let before = source_stamp(&path).unwrap();
        let file = fs::OpenOptions::new().write(true).open(&path).unwrap();
        file.set_times(
            std::fs::FileTimes::new()
                .set_modified(std::time::UNIX_EPOCH + Duration::new(1_700_000_000, 123_456_700)),
        )
        .unwrap();
        drop(file);
        let after = source_stamp(&path).unwrap();
        assert_eq!(after, stamp(&path));
        assert_eq!(before.0, after.0);
        assert_ne!(before.1, after.1);
        fs::write(&path, b"longer").unwrap();
        assert_eq!(source_stamp(&path), Some(stamp(&path)));
        assert_ne!(source_stamp(&path).unwrap().0, before.0);
        fs::remove_file(&path).unwrap();
        assert_eq!(source_stamp(&path), None);
        assert_eq!(source_stamp(&temp.0), None);
        assert_eq!(source_stamp(&temp.0.join("bad\0name.fdb")), None);
    }

    #[test]
    fn symbolic_links_require_the_existing_following_metadata_path() {
        let temp = Temp::new();
        let path = temp.0.join("source.fdb");
        let link = temp.0.join("link.fdb");
        fs::write(&path, b"payload").unwrap();
        match std::os::windows::fs::symlink_file(&path, &link) {
            Ok(()) => {
                assert_eq!(source_stamp(&link), None);
                assert_eq!(stamp(&link), stamp(&path));
            }
            Err(error)
                if error.kind() == std::io::ErrorKind::PermissionDenied
                    || error.raw_os_error()
                        == Some(
                            windows_sys::Win32::Foundation::ERROR_PRIVILEGE_NOT_HELD as i32,
                        ) =>
            {
                eprintln!("symlink runtime check unavailable: {error}");
            }
            Err(error) => panic!("symlink setup failed: {error}"),
        }
    }
}
